// The asset set every seed registers in src/assets.json, with identical keys,
// URLs and descriptions in all three arms. Templates keep their own entries;
// these are added next to them. Local files are generated by make-assets.mjs
// into public/<SHARED_ASSET_DIR>/ and referenced relatively so they resolve
// under both the dev server and a `--base ./` production build.
export const SHARED_ASSET_DIR = "eval-assets";

const CDN = "https://agent8-games.verse8.io/assets/3d";
const anim = (file, description) => ({ url: `${CDN}/animations/mixamorig/${file}`, description });
const local = (file, description) => ({ url: `${SHARED_ASSET_DIR}/${file}`, description });

export const SHARED_ASSETS = {
  characters: {
    knight: {
      url: `${CDN}/characters/human/knight.glb`,
      description: "Knight character (rigged, mixamorig skeleton; use with the knight-* animations)",
    },
  },
  animations: {
    "knight-idle": anim("idle-00.glb", "Idle (mixamorig)"),
    "knight-walk": anim("walk.glb", "Walk (mixamorig)"),
    "knight-run": anim("run-medium.glb", "Run (mixamorig)"),
    "knight-jump": anim("jump.glb", "Jump (mixamorig)"),
    "knight-shoot": anim("shoot.glb", "Shoot (mixamorig)"),
    "knight-hit": anim("hit.glb", "Hit reaction (mixamorig)"),
    "knight-death": anim("death.glb", "Death (mixamorig)"),
  },
  sounds: {
    "sfx-jump": local("jump.wav", "Jump sound effect"),
    "sfx-land": local("land.wav", "Landing sound effect"),
    "sfx-coin": local("coin.wav", "Coin / pickup sound effect"),
    "sfx-shoot": local("shoot.wav", "Shot sound effect"),
    "sfx-hit": local("hit.wav", "Hit / damage sound effect"),
    "sfx-explode": local("explode.wav", "Explosion / enemy destroyed sound effect"),
  },
  textures: {
    sky: local("sky.png", "Sky panorama (equirectangular 2:1)"),
  },
};
